insert into public.word_examples (word_id, order_index, sentence_en, sentence_vi) values
('00000901-0000-4000-8000-000000000901', 1, 'I keep my money in the bank.', 'Tôi giữ tiền trong ngân hàng.'),
('00000901-0000-4000-8000-000000000901', 2, 'She saves money every month.', 'Cô ấy để dành tiền mỗi tháng.'),
('00000901-0000-4000-8000-000000000901', 3, 'How much money do you need?', 'Bạn cần bao nhiêu tiền?'),
('00000902-0000-4000-8000-000000000902', 1, 'She dropped a coin on the floor.', 'Cô ấy làm rơi một đồng xu xuống sàn.'),
('00000902-0000-4000-8000-000000000902', 2, 'The machine only takes coins.', 'Cái máy này chỉ nhận tiền xu.'),
('00000902-0000-4000-8000-000000000902', 3, 'He collects old coins.', 'Anh ấy sưu tầm tiền xu cổ.'),
('00000903-0000-4000-8000-000000000903', 1, 'This banknote is torn.', 'Tờ tiền này bị rách.'),
('00000903-0000-4000-8000-000000000903', 2, 'The machine does not accept old banknotes.', 'Máy không nhận tờ tiền cũ.'),
('00000903-0000-4000-8000-000000000903', 3, 'She folded the banknote and put it away.', 'Cô ấy gấp tờ tiền lại rồi cất đi.'),
('00000904-0000-4000-8000-000000000904', 1, 'There is an ATM near the gate.', 'Có một máy rút tiền gần cổng.'),
('00000904-0000-4000-8000-000000000904', 2, 'The ATM is out of money.', 'Máy rút tiền hết tiền rồi.'),
('00000904-0000-4000-8000-000000000904', 3, 'I use the ATM at the supermarket.', 'Tôi dùng máy rút tiền ở siêu thị.'),
('00000905-0000-4000-8000-000000000905', 1, 'I want to deposit five million dong.', 'Tôi muốn gửi vào năm triệu đồng.'),
('00000905-0000-4000-8000-000000000905', 2, 'You must pay a deposit for the room.', 'Bạn phải đặt cọc cho căn phòng.'),
('00000905-0000-4000-8000-000000000905', 3, 'He deposits his salary every month.', 'Anh ấy gửi lương vào tài khoản mỗi tháng.'),
('00000906-0000-4000-8000-000000000906', 1, 'You can withdraw money at any ATM.', 'Bạn có thể rút tiền ở bất kỳ máy ATM nào.'),
('00000906-0000-4000-8000-000000000906', 2, 'She withdrew two million dong yesterday.', 'Hôm qua cô ấy rút hai triệu đồng.'),
('00000906-0000-4000-8000-000000000906', 3, 'I need to withdraw some cash first.', 'Tôi cần rút ít tiền mặt trước đã.'),
('00000907-0000-4000-8000-000000000907', 1, 'Please transfer the money today.', 'Vui lòng chuyển khoản tiền trong hôm nay.'),
