-- 4. Cap nhat quy mo chuong trinh hoc
update public.courses set total_words = 1000,
       description = 'Bộ 1000 từ thông dụng chia theo 20 chủ đề đời sống'
where id = 'e0000000-0000-4000-8000-000000000005';

